# Textos das missões: comando(s) esperados e resultado simulado, sem executar Git real.
missions=[
 dict(title='A central de ferramentas',story='A prefeitura vai digitalizar os serviços. Antes de começar, descubra se o Git está disponível no computador da equipe.',goal='Verifique a versão do Git usando o terminal.',steps=[('version','Verificar instalação','git --version','git version 2.x (ambiente simulado)')],lesson='git --version exibe a versão do Git instalada. O Git gerencia o histórico de versões localmente.'),
 dict(title='Quem está programando?',story='O sistema precisa identificar quem registrou cada alteração. Configure o nome de autoria que será associado aos futuros commits.',goal='Configure um nome de usuário global. Você pode usar um nome fictício.',steps=[('name','Definir autor','git config --global user.name "Ana Silva"','Nome global de autoria configurado.')],lesson='git config --global user.name define o nome de autoria padrão dos commits nesse computador. Não é o nome de usuário do GitHub.'),
 dict(title='Assinatura do commit',story='A equipe precisa associar um e-mail à autoria dos commits. Use um endereço fictício para praticar.',goal='Configure o e-mail global de autoria no Git.',steps=[('email','Definir e-mail','git config --global user.email "ana@exemplo.com"','E-mail global de autoria configurado.')],lesson='git config --global user.email registra o e-mail de autoria padrão. Em um projeto real, o e-mail pode ser ajustado por repositório e deve respeitar a privacidade do usuário.'),
 dict(title='Fundação do repositório',story='O projeto Cidade Digital ainda é uma pasta comum. Transforme-a em um repositório Git, iniciando o branch principal como main.',goal='Inicialize o repositório usando main como branch inicial.',steps=[('init','Iniciar versionamento','git init -b main','Initialized empty Git repository in cidade-digital/.git/')],lesson='git init inicia o repositório local. A opção -b main define o nome do branch inicial explicitamente.'),
 dict(title='Detetives do código',story='Os estudantes editaram index.html e não sabem se as mudanças já estão prontas para registrar. Consulte o estado atual.',goal='Confira os arquivos modificados no repositório.',steps=[('status','Inspecionar mudanças','git status','On branch main\nChanges not staged for commit:\n  modified: index.html')],lesson='git status mostra o branch atual, os arquivos alterados e o que já está preparado para o próximo commit.'),
 dict(title='Antes e depois',story='Uma nova seção foi adicionada à página inicial. O coordenador quer conferir exatamente o que mudou antes de salvar a versão.',goal='Visualize as diferenças ainda não preparadas.',steps=[('diff','Inspecionar diferenças','git diff','diff --git a/index.html b/index.html\n+ <section>Serviços da cidade</section>')],lesson='git diff mostra diferenças não adicionadas ao staging. Para mudanças já preparadas, utilize git diff --staged.'),
 dict(title='Preparar a entrega',story='O arquivo index.html foi revisado e está pronto para entrar na próxima versão do site.',goal='Adicione apenas index.html à área de preparação (staging).',steps=[('addIndex','Preparar arquivo','git add index.html','Arquivo index.html adicionado ao staging.'),('diffStaged','Conferir o staging','git diff --staged','diff --git a/index.html b/index.html\n+ <section>Serviços da cidade</section>')],lesson='git add coloca uma cópia do conteúdo atual no staging. O commit só inclui aquilo que foi preparado.'),
 dict(title='Primeiro ponto de controle',story='O site inicial está aprovado. Agora é hora de registrar uma versão com uma mensagem que descreva a mudança.',goal='Crie o primeiro commit com uma mensagem descritiva.',steps=[('commitMain','Registrar alteração','git commit -m "Cria pagina inicial"','[main a1b2c3d] Cria pagina inicial\n 1 file changed'),('logOne','Consultar histórico resumido','git log --oneline','a1b2c3d Cria pagina inicial')],lesson='git commit -m "mensagem" registra no histórico as mudanças que estavam no staging. Fazer commit não envia o conteúdo ao GitHub.'),
 dict(title='Uma rua só para o menu',story='O estudante responsável pelo menu quer trabalhar sem modificar o branch main até a funcionalidade ficar pronta.',goal='Crie e acesse o branch feature/menu.',steps=[('branchFeature','Criar branch de funcionalidade','git switch -c feature/menu','Switched to a new branch: feature/menu'),('listBranches','Listar branches locais','git branch','* feature/menu\n  main')],lesson='git switch -c cria um branch e já muda para ele. Também existe git checkout -b, comando tradicional com o mesmo efeito nessa situação.'),
 dict(title='Revisão no branch',story='O menu foi escrito no arquivo menu.js. Antes de preparar a alteração, confira as linhas acrescentadas.',goal='Examine as diferenças no branch feature/menu.',steps=[('diffFeature','Conferir o código','git diff','diff --git a/menu.js b/menu.js\n+ function abrirMenu() { /* ... */ }')],lesson='git diff funciona no branch atual e permite revisar o que mudou na árvore de trabalho.'),
 dict(title='Entrega isolada',story='A funcionalidade de menu foi testada e precisa ser registrada no histórico do seu próprio branch.',goal='Prepare menu.js e depois faça um commit descritivo.',steps=[('addMenu','Preparar menu.js','git add menu.js','menu.js preparado para o commit.'),('commitMenu','Registrar o menu','git commit -m "Adiciona menu"','[feature/menu d4e5f6a] Adiciona menu')],lesson='Faça git add no arquivo desejado e depois git commit. Esse commit permanece no branch feature/menu até ser integrado.'),
 dict(title='Avenida da integração',story='O menu está concluído e deve fazer parte do projeto principal. Integre o branch de funcionalidade na direção correta.',goal='Volte para main e mescle feature/menu nela.',steps=[('switchMain','Voltar ao principal','git switch main','Switched to branch main'),('mergeFeature','Integrar o menu','git merge feature/menu','Updating a1b2c3d..d4e5f6a\nFast-forward\n menu.js | 1 +')],lesson='Para mesclar feature/menu em main, esteja em main e execute git merge feature/menu. Em projetos reais pode haver conflitos, que exigem resolução manual.'),
 dict(title='Conexão com a nuvem',story='A prefeitura criou um repositório vazio no GitHub e quer associá-lo ao projeto local. O endereço mostrado é ilustrativo.',goal='Cadastre um remoto chamado origin com uma URL do GitHub.',steps=[('remoteAdd','Associar remoto','git remote add origin https://github.com/equipe/cidade-digital.git','Remoto origin cadastrado na simulação.')],lesson='git remote add origin URL associa um nome a um repositório remoto. O comando não cria o repositório no GitHub.'),
 dict(title='Inspecionar conexão',story='Antes de enviar arquivos, confirme se o endereço remoto ficou registrado corretamente.',goal='Liste os remotos configurados e suas URLs.',steps=[('remoteList','Listar conexões','git remote -v','origin  https://github.com/equipe/cidade-digital.git (fetch)\norigin  https://github.com/equipe/cidade-digital.git (push)')],lesson='git remote -v mostra os endereços usados para buscar e enviar conteúdo. O nome origin é apenas uma convenção.'),
 dict(title='Publicar o projeto',story='O projeto já tem commits locais. A equipe precisa publicar o branch main no repositório remoto.',goal='Envie main para origin e configure o rastreamento.',steps=[('pushMain','Publicar branch main','git push -u origin main','Branch main publicado em origin (simulação).\nTracking branch configurado.')],lesson='git push envia commits ao remoto; -u define o branch upstream para facilitar futuros push e pull. É preciso permissão e autenticação em um GitHub real.'),
 dict(title='Atualização da equipe',story='Outra pessoa atualizou o remoto e você precisa trazer a versão mais recente. Primeiro consulte o remoto sem modificar seus arquivos; depois atualize main.',goal='Execute fetch e, em seguida, pull de origin/main.',steps=[('fetch','Consultar remoto','git fetch origin','Objetos e referências remotas atualizados. Arquivos locais preservados.'),('pull','Atualizar main','git pull origin main','Already up to date. (situação simulada, sem conflitos)')],lesson='git fetch baixa referências e objetos sem integrar automaticamente as alterações. git pull busca e integra o histórico remoto ao branch atual.'),
 dict(title='Novo projeto da escola',story='Chegou outra demanda: colaborar no Portal Escola, que já existe no GitHub. Comece obtendo uma cópia local desse projeto.',goal='Clone o repositório ilustrativo da escola.',steps=[('clone','Clonar projeto','git clone https://github.com/equipe/portal-escola.git','Cloning into portal-escola...\nClone simulado concluído.')],lesson='git clone URL cria uma cópia local de um repositório existente, normalmente com origin configurado. A URL desta atividade é um exemplo fictício.'),
 dict(title='Tela de contato em equipe',story='Uma aluna vai construir o formulário de contato no projeto da escola, sem alterar imediatamente o branch principal.',goal='Crie o branch feature/contato no projeto clonado.',steps=[('branchContact','Criar branch de contato','git switch -c feature/contato','Switched to a new branch feature/contato')],lesson='Cada funcionalidade pode ser desenvolvida em seu próprio branch. Isso facilita revisões e reduz alterações diretas em main.'),
 dict(title='Enviar a colaboração',story='O arquivo contato.html está pronto. Registre-o com um commit e publique o branch para que a equipe possa revisar.',goal='Adicione contato.html, registre o commit e envie o branch.',steps=[('addContact','Preparar contato.html','git add contato.html','contato.html preparado.'),('commitContact','Registrar nova tela','git commit -m "Cria pagina de contato"','[feature/contato e7f8a9b] Cria pagina de contato'),('pushContact','Publicar branch','git push -u origin feature/contato','Branch feature/contato publicado no remoto (simulação).')],lesson='Para colaborar: crie o branch, altere arquivos, prepare, faça commit e publique. Depois proponha a integração por pull request no GitHub.'),
 dict(title='A revisão final',story='O branch feature/contato foi enviado. Antes de integrar o trabalho ao principal, a equipe quer examinar as alterações por meio de um pull request.',goal='Simule a criação, a revisão e a mesclagem de um pull request no GitHub.',steps=[('prCreate','Criar pull request','Acessar GitHub → New pull request','Pull request aberto: feature/contato → main'),('prReview','Revisar alterações','Revisar arquivos e aprovar','Revisão aprovada pela equipe.'),('prMerge','Concluir integração','Merge pull request','Pull request mesclado em main.')],lesson='Pull request é um recurso de colaboração do GitHub, não um comando básico do Git. A revisão ocorre antes de integrar o branch de contribuição ao branch de destino.'),
]
